///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSaveId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSaveId = async function () {
    const sbmOptions = {
        id: "tx_fnSaveId",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_fnSaveIdReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf06000.tx_fnSaveId" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_checkUsrId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_checkUsrId = async function () {
    const sbmOptions = {
        id: "tx_fn_checkUsrId",
        method: "post",
        action: "/corp/register.do?method=searchUsrId",
        ref: "dma_checkUsrIdReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf06000.tx_fn_checkUsrId" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.changeId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeId = function () {
    /* sdd-asis-lifecycle:begin fn_changeId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.SendForm || { elements: [] });
    const oldIdVal = $c.util.getComponent('dma_fnSaveIdReq').get('usrId').replace(/ /gi, "");
    if (oldIdVal !== "") {
        $c.util.getComponent('ipt_message').setValue("");
        $("input[name='newYn']").val("");
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.idChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.idChk = async function () {
    /* sdd-asis-lifecycle:begin idChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_nowid').getValue()) == 0) {
        await $c.win.alert("현재 아이디를 입력하세요");
        $c.util.getComponent("ipt_nowid").focus();
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_chgid').getValue()) == 0) {
            await $c.win.alert("변경 아이디를 입력하세요");
            $c.util.getComponent("ipt_chgid").focus();
        } else {
            if ($c.str.getByteLength($c.util.getComponent('dma_fnSaveIdReq').get('newYn')) == 0 || $c.util.getComponent('dma_fnSaveIdReq').get('newYn') === 'N') {
                await $c.win.alert("아이디 중복확인 여부를 확인하십시오.");
                $c.util.getComponent("ipt_chgid").focus();
            } else {
                if (await $c.win.confirm("변경하시겠습니까?")) {
                    scwin.fnNowIdCheck();
                    await scwin.fnSaveId();
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnNowIdCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnNowIdCheck = function () {
    /* sdd-asis-lifecycle:begin fnNowIdCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const base_url = "";
    let action_path = "";
    action_path = "/account/userId.do";
    $("input[name='method']").val("checkNowId");
    $.ajax({ type: "POST", async: false, url: base_url + action_path, data: $("#SendForm").serialize(), success: function(data) {
                scwin.result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                $c.util.getComponent('ipt_temp').setValue(scwin.result.sendResult);
            }, error: async function(request, status, error) {
                await $c.win.alert("현재 아이디를 조회 할 수 없습니다. 관리자에게 문의하십시오.");
                return;
            }, complete: function() {

            } });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSaveId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSaveId = async function () {
    /* sdd-asis-lifecycle:begin fnSaveId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.util.getComponent('ipt_temp').getValue() === '-1') {
        await $c.win.alert("현재 아이디가 일치하지 않습니다.");
        return;
    } else {
        if ($c.util.getComponent('ipt_temp').getValue() === 'R') {
            await $c.win.alert("현재 신청 중인 건이 존재합니다.\n신청중인 건이 존재할 경우 ID변경이 불가합니다.");
            return;
        } else {
            $c.util.getComponent('dma_fnSaveIdReq').set('method', "updateIntegUsrId");
            fm.action = "/account/userPw.do";
            fm.target = "_self";
            await scwin.tx_fnSaveId();
        }
    }
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.checkUsrIdDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.checkUsrIdDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_checkUsrId_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_message').setValue(result.message);
    $("input[name='newYn']").val(result.newYn);
    $("input[name='old_integ_usr_id']").val(SendForm.integ_usr_id.value);
    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.checkUsrId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkUsrId = async function () {
    const r = await scwin.tx_fn_checkUsrId();
    try {
        scwin.checkUsrIdDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldinf06000.fn_checkUsrId' });
    }
    return r;
};
